def baseline_state(baseline, desktop, desktop_raw):
    """Bind only the six existing settings files present in the outer census."""
    wanted={
        '/home/peachyprototype/JustPeachy/install/current.json',
        '/home/peachyprototype/JustPeachy/data/live_config.json',
        '/home/peachyprototype/JustPeachy/data/settings.json',
        '/home/peachyprototype/.config/kanshi/config',
        '/home/peachyprototype/.config/autostart/just-peachy.desktop',
        '/home/peachyprototype/JustPeachy/start-prototype.sh'}
    rows=list(baseline['files'])+list(baseline['startup_files'])+[baseline['launcher_backup']]
    pins=[]
    for path in sorted(wanted):
        found=[row for row in rows if row.get('path')==path]
        if len(found)!=1:raise ValueError('Exact fresh-baseline settings membership required: '+path)
        row=found[0]
        if type(row.get('bytes')) is not int or not 0<=row['bytes']<=65536 or re.fullmatch('[0-9a-f]{64}',row.get('sha256','')) is None:
            raise ValueError('Bounded settings pin required')
        pins.append(dict(path=path,bytes=row['bytes'],sha256=row['sha256']))
    auto=next(row for row in pins if '/autostart/' in row['path'])
    if baseline['actual_autostart_pin']!=dict(bytes=auto['bytes'],sha256=auto['sha256']):
        raise ValueError('Fresh autostart pin differs')
    pins.append(dict(path=str(desktop),bytes=len(desktop_raw),sha256=hashlib.sha256(desktop_raw).hexdigest()))
    display=baseline['display'];capture=baseline['capture']
    if (display['returncode']!=0 or 'Enabled: yes' not in display['stdout'] or 'Transform: 270' not in display['stdout']
            or len(display['stdout'])+len(display['stderr'])>32768):raise ValueError('Fresh display270 baseline required')
    if (baseline.get('capture_started') is not False or not isinstance(capture,dict) or not 1<=len(capture)<=8
            or any(re.fullmatch('/proc/asound/card[0-9]+/pcm[0-9]+c/sub[0-9]+/status',path) is None or value!='closed'
                for path,value in capture.items())):raise ValueError('Fresh closed capture baseline required')
    return dict(unchanged_files=pins,capture_status=capture,
        display_stdout_sha256=hashlib.sha256(display['stdout'].encode('utf-8')).hexdigest())


def dispatch(p, baseline):
    if p.get('verify_optional_policy') is not True:
        raise ValueError('Explicit production optional-policy idle inspection required')
    if any(baseline.get(key) for key in ('current_project_processes','active_recorded_owners','live_manager_owners','held_research_leases')):
        raise ValueError('Fresh closed process/lease baseline required')
    boot=Path('/proc/sys/kernel/random/boot_id').read_text().strip()
    if p['boot_id']!=boot or not time.time()<p['expires_unix']<=time.time()+600:
        raise ValueError('Fresh exact boot admission required')
    campaign=Path('/home/peachyprototype/JustPeachy/research/nemotron-20260928')
    package=Path(p['package']);desktop=Path(p['desktop'])
    if (package.parent!=campaign or re.fullmatch(r'field-runtime-v29-build-[0-9]{2}',package.name) is None
            or desktop.parent!=Path('/home/peachyprototype/Desktop') or desktop.suffix!='.desktop'
            or p.get('maximum_output_bytes')!=16*1024**2):
        raise ValueError('Exact production package/shortcut and16MiB reservation required')
    for path in (package,desktop):
        if path.resolve(strict=True)!=path:raise ValueError('Canonical production paths required')
    manifest_path=package/'PACKAGE_MANIFEST.json';raw=manifest_path.read_bytes()
    if len(raw)>262144 or hashlib.sha256(raw).hexdigest()!=p['package_manifest_sha256']:
        raise ValueError('Exact production package manifest required')
    manifest=json.loads(raw)
    entry=next(row for row in manifest['files'] if row['path']=='launch_raw_qualification_action.py')
    helper_path=package/entry['path'];source=helper_path.read_bytes()
    if (helper_path.resolve(strict=True)!=helper_path or len(source)>131072 or
            (len(source),hashlib.sha256(source).hexdigest())!=(entry['bytes'],entry['sha256'])):
        raise ValueError('Pinned shared owner/unit wrapper required')
    helper=dict(__name__='verified_idle_wrapper',__file__=str(helper_path))
    exec(compile(source,str(helper_path),'exec'),helper)
    helper['inventory'](package,p['package_manifest_sha256'])
    binding=json.loads((package/'BINDING.json').read_bytes())
    acceptance=(package/'PRODUCTION_ACCEPTANCE.json').read_bytes()
    if (binding.get('target')!=str(package) or binding.get('authorization_kind')!='production'
            or binding.get('native_launch_enabled') is not True
            or hashlib.sha256(acceptance).hexdigest()!=p['production_acceptance_sha256']
            or binding.get('production_acceptance_sha256')!=p['production_acceptance_sha256']):
        raise ValueError('Exact production acceptance required')
    if desktop.stat().st_nlink!=1 or not desktop.is_file():raise ValueError('Single-link current desktop required')
    raw=desktop.read_bytes()
    expected=('Exec='+binding['python']+' -B '+str(package/'native_scope.py')+' --binding '+str(package/'BINDING.json')+
        ' --manifest-sha256 '+p['package_manifest_sha256']+' --data-root /home/peachyprototype/JustPeachy/data/runtime-v29')
    if len(raw)>65536 or hashlib.sha256(raw).hexdigest()!=p['desktop_sha256'] or raw.decode().splitlines().count(expected)!=1:
        raise ValueError('Exact activated production desktop command required')
    unchanged=baseline_state(baseline,desktop,raw)
    label=p['label']
    if re.fullmatch(r'production-idle-[0-9]{2}',label) is None:raise ValueError('Fresh production idle label required')
    if shutil.disk_usage(campaign).free<5*1024**3+16*1024**2:raise OSError('Native disk floor and full metadata allocation required')
    unit='jp-v29-'+label+'.service';out=campaign/'live-runtime-tests-20261003'/label
    prior=subprocess.run(['systemctl','--user','show',unit,'--property=LoadState'],capture_output=True,text=True,timeout=5)
    if prior.stdout.strip()!='LoadState=not-found':raise ValueError('Fresh unique production idle unit required')
    if out.parent.resolve(strict=True)!=out.parent:raise ValueError('Canonical output parent required')
    environment=subprocess.run(['systemctl','--user','show-environment'],capture_output=True,text=True,timeout=5,check=True)
    if len(environment.stdout)>65536:raise ValueError('Desktop environment bound')
    env=dict(line.split('=',1) for line in environment.stdout.splitlines() if '=' in line)
    if not env.get('DISPLAY') or not env.get('XDG_RUNTIME_DIR'):raise ValueError('Existing desktop environment required')
    data_root=Path('/home/peachyprototype/JustPeachy/data/runtime-v29')
    if data_root.is_symlink() or data_root.parent.resolve(strict=True)!=data_root.parent:
        raise ValueError('Canonical exact default production data root required')
    if data_root.exists() and (not data_root.is_dir() or next(data_root.iterdir(),None) is not None):
        raise ValueError('Idle proof requires the actual default data root absent or empty; preserve existing data')
    watchdog_unit='jp-v29-'+label+'-watchdog.service'
    prior_watchdog=subprocess.run(['systemctl','--user','show',watchdog_unit,'--property=LoadState'],capture_output=True,text=True,timeout=5)
    if prior_watchdog.stdout.strip()!='LoadState=not-found':raise ValueError('Fresh independent watchdog unit required')
    out.mkdir();put=helper['put']
    put(out/'BASELINE.json',baseline)
    put(out/'IDLE_REQUEST.json',dict(package=str(package),scope_sha256=helper['sha'](package/'native_scope.py'),
        boot_id=boot,desktop=str(desktop),desktop_sha256=p['desktop_sha256'],data_root=str(data_root),
        data_root_precondition='absent_or_empty',command=shlex.split(expected[5:]),watchdog_unit=watchdog_unit,
        baseline_sha256=helper['sha'](out/'BASELINE.json'),**unchanged))
    settings=dict(output=str(out),package=str(package),unit=unit,boot_id=boot,expires_unix=p['expires_unix'],
        package_manifest_sha256=p['package_manifest_sha256'],scope_sha256=helper['sha'](package/'native_scope.py'),
        research_lock=str(campaign/'B05_PREVIEW_DISPATCH.lock'),kind='production_idle',template=None,
        budget=dict(maximum_output_bytes=16*1024**2,runtime_seconds=120,stop_seconds=30,file_limit_bytes=32*1024**2),
        argv=[str(out/'idle_control.py'),str(out)])
    wrapper=helper['wrapper_source'](settings).encode()
    for name,value in (('idle_control.py',CONTROL_SOURCE.encode()),('wrapper.py',wrapper)):
        with (out/name).open('xb') as stream:
            if stream.write(value)!=len(value):raise OSError('Short idle preparation write')
            stream.flush();os.fsync(stream.fileno())
        if (out/name).read_bytes()!=value:raise OSError('Idle preparation readback differs')
    put(out/'ADMISSION.json',dict(payload=p,driver_sha256=hashlib.sha256(CONTROL_SOURCE.encode()).hexdigest(),
        wrapper_sha256=hashlib.sha256(wrapper).hexdigest(),capture=False,models_constructed=False,
        native_reservation_bytes=16*1024**2,independent_host_reservation_bytes=16*1024**2))
    args=['systemd-run','--user','--unit='+unit,'--description=JustPeachyProductionIdle',
        '--property=AllowedCPUs=2,3','--property=CPUQuota=200%','--property=TasksMax=64',
        '--property=RuntimeMaxSec=120','--property=TimeoutStopSec=30','--property=KillMode=control-group',
        '--setenv=PYTHONDONTWRITEBYTECODE=1','--setenv=MALLOC_ARENA_MAX=1','--setenv=MALLOC_MMAP_THRESHOLD_=131072','--setenv=MALLOC_TRIM_THRESHOLD_=131072']
    args += ['--setenv='+key+'='+env[key] for key in ('DISPLAY','WAYLAND_DISPLAY','XDG_RUNTIME_DIR','XAUTHORITY','DBUS_SESSION_BUS_ADDRESS') if env.get(key)]
    args += [binding['python'],'-B',str(out/'wrapper.py')]
    started=subprocess.run(args,capture_output=True,text=True,timeout=10)
    put(out/'SYSTEMD_RUN.json',dict(returncode=started.returncode,stdout=started.stdout[:4096],stderr=started.stderr[:4096]))
    if started.returncode:raise RuntimeError('Production idle unit did not launch')
    end=time.monotonic()+5
    while not (out/'OWNER.json').exists() and time.monotonic()<end:time.sleep(.05)
    owner=json.loads((out/'OWNER.json').read_bytes()) if (out/'OWNER.json').exists() else None
    shown=subprocess.run(['systemctl','--user','show',unit,'--property=InvocationID,MainPID,ActiveState,ControlGroup'],
        capture_output=True,text=True,timeout=5,check=True)
    props=dict(line.split('=',1) for line in shown.stdout.splitlines() if '=' in line)
    job=dict(schema='just-peachy.native-component-job.v1',boot_id=boot,unit=unit,owner=owner,
        invocation_id=props.get('InvocationID'),control_group=props.get('ControlGroup'),properties=props,
        output_root=str(out),maximum_output_bytes=16*1024**2,package_manifest_sha256=p['package_manifest_sha256'],
        issued_unix=time.time(),deadline_unix=time.time()+165)
    put(out/'JOB.json',job);return job


if 'PAYLOAD' in globals():RESULT=dispatch(PAYLOAD,BASELINE)
